import process from 'node:process';
import { Buffer } from 'node:buffer';
import { Router } from "npm:express@5.2.1";
import { db, PHOTO_SELECT } from '../db.js';
import { requireUser } from '../auth.js';
import { HttpError, publicUser, shapePhoto } from '../util.js';
export const users = Router();
export const me = Router();
users.get('/:username', async (req, res) => {
  const user = await db.prepare('SELECT * FROM users WHERE username = ?').get(req.params.username);
  if (!user) throw new HttpError(404, 'Fotógrafo não encontrado.');
  const photos = await Promise.all((await db.prepare(`${PHOTO_SELECT} WHERE p.user_id = ? AND p.status = 'approved' ORDER BY p.created_at DESC, p.id DESC`).all(user.id)).map(async r => await shapePhoto(r, req.user)));
  const {
    email,
    role,
    ...profile
  } = publicUser(user);
  const featuredCount = (await db.prepare(`SELECT COUNT(DISTINCT f.photo_id) AS n FROM featured f
      JOIN photos p ON p.id = f.photo_id WHERE p.user_id = ?`).get(user.id)).n;
  res.json({
    user: {
      ...profile,
      joinedAt: user.created_at,
      featuredCount
    },
    photos,
    isOwner: req.user?.id === user.id,
    followers: (await db.prepare('SELECT COUNT(*) AS n FROM follows WHERE followed_id = ?').get(user.id)).n,
    following: !!req.user && !!(await db.prepare('SELECT 1 FROM follows WHERE follower_id = ? AND followed_id = ?').get(req.user.id, user.id)),
    notifyEmail: !!req.user && !!(await db.prepare('SELECT 1 FROM follows WHERE follower_id = ? AND followed_id = ? AND notify_email = 1').get(req.user.id, user.id))
  });
});
me.get('/photos', requireUser, async (req, res) => {
  const rows = await db.prepare(`${PHOTO_SELECT} WHERE p.user_id = ? ORDER BY p.created_at DESC, p.id DESC`).all(req.user.id);
  res.json({
    photos: await Promise.all(rows.map(async r => await shapePhoto(r, req.user)))
  });
});
me.get('/inspired', requireUser, async (req, res) => {
  const rows = await db.prepare(`${PHOTO_SELECT}
      JOIN inspired i ON i.photo_id = p.id
      WHERE i.user_id = ? AND p.status = 'approved'
      ORDER BY i.created_at DESC`).all(req.user.id);
  res.json({
    photos: await Promise.all(rows.map(async r => await shapePhoto(r, req.user)))
  });
});
users.post('/:username/follow', requireUser, async (req, res) => {
  const user = await db.prepare('SELECT id FROM users WHERE username = ?').get(req.params.username);
  if (!user) throw new HttpError(404, 'Fotógrafo não encontrado.');
  if (user.id === req.user.id) throw new HttpError(400, 'Não podes seguir o teu próprio perfil.');
  if (req.body.notifyEmail !== undefined && typeof req.body.notifyEmail !== 'boolean') throw new HttpError(400, 'Preferência inválida.');
  await db.prepare(`INSERT INTO follows (follower_id,followed_id,notify_email) VALUES (?,?,?)
    ON CONFLICT(follower_id,followed_id) DO UPDATE SET notify_email = excluded.notify_email`).run(req.user.id, user.id, Number(req.body.notifyEmail === true));
  if (req.body.notifyEmail !== true) await db.prepare('UPDATE follower_notifications SET email_requested = 0 WHERE user_id = ? AND emailed_at IS NULL AND photo_id IN (SELECT id FROM photos WHERE user_id = ?)').run(req.user.id, user.id);
  res.json({
    ok: true
  });
});
users.delete('/:username/follow', requireUser, async (req, res) => {
  const user = await db.prepare('SELECT id FROM users WHERE username = ?').get(req.params.username);
  if (user) {
    await db.prepare('DELETE FROM follows WHERE follower_id = ? AND followed_id = ?').run(req.user.id, user.id);
    await db.prepare('UPDATE follower_notifications SET email_requested = 0 WHERE user_id = ? AND emailed_at IS NULL AND photo_id IN (SELECT id FROM photos WHERE user_id = ?)').run(req.user.id, user.id);
  }
  res.json({
    ok: true
  });
});
